mapper.select:
SELECT *
FROM schedule
WHERE doctor_id = #{doctorId}
  AND work_date = #{workDate}
  AND registered_count < max_patients

SELECT s.*
FROM schedule s
INNER JOIN doctor d ON s.doctor_id = d.id
LEFT JOIN department dept ON d.department_id = dept.id
WHERE 1 = 1

    AND dept.id = #{deptId}


    AND s.work_date = #{workDate}


    AND s.time_slot = #{timeSlot}

ORDER BY s.work_date DESC, dept.sort_order, d.id, s.time_slot

